// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "./StreamMintPhaseState.sol";
import "./StreamMintManagerAccounting.sol";
import "../../interfaces/stream/parameters/IStreamGasParameterHost.sol";

/// @notice Original consent-gated policy refresh through a fixed linked boundary.
/// @dev Manager retains owner/reentrancy and configured-phase admission.
/// Delegatecall keeps its storage, identity and event emitter; the artist cap is
/// read from the actual Manager at the original post-hash consent phase.
library StreamMintManagerPolicy {
    struct Context {
        StreamMintOperationIdentity.PolicyContext policy;
        address core;
    }

    struct ExecutorUpdate {
        Context context;
        address executor;
        bool allowed;
        uint64 graceUntil;
        uint16 maxExecutors;
    }

    uint16 private constant SCHEMA_VERSION = 1;
    bytes32 private constant GGP_ARTIST_AUTHORITY_GAS_LIMIT =
        keccak256("6529STREAM_GGP_ARTIST_AUTHORITY_GAS_LIMIT");

    event MintPhaseConsentRecorded(
        uint16 schemaVersion,
        uint256 indexed collectionId,
        bytes32 indexed phaseId,
        bytes32 indexed policyHash,
        uint8 consentMode,
        bytes32 consentEvidenceHash
    );

    event MintPhaseExecutorUpdated(
        uint256 indexed collectionId,
        bytes32 indexed phaseId,
        address indexed executor,
        bool allowed,
        bytes32 policyHash,
        address admin
    );

    /// @notice Applies one original executor mutation and consented policy refresh atomically.
    /// @dev All storage references and the maximum originate at the guarded Manager entrypoint.
    function updateExecutor(
        StreamMintPhaseState.PhaseState storage phaseState,
        IStreamMintManager.MintGateConfig storage gate,
        bytes32[] storage counterIds,
        mapping(bytes32 => IStreamMintManager.MintCounterConfig) storage counters,
        mapping(address => bool) storage authorized,
        address[] storage executors,
        mapping(address => uint256) storage indexPlusOne,
        mapping(bytes32 => bytes32) storage policyHashes,
        ExecutorUpdate memory update
    ) external {
        if (!StreamMintPhaseState.setExecutor(
                authorized,
                executors,
                indexPlusOne,
                update.executor,
                update.allowed,
                update.maxExecutors
            )) {
            if (update.graceUntil != 0) {
                revert IStreamMintLedger.InvalidPolicyGrace(update.graceUntil);
            }
            return;
        }
        bytes32 policyHash = _refresh(
            phaseState,
            gate,
            counterIds,
            counters,
            executors,
            policyHashes,
            update.context,
            update.graceUntil
        );
        emit MintPhaseExecutorUpdated(
            update.context.policy.collectionId,
            update.context.policy.phaseId,
            update.executor,
            update.allowed,
            policyHash,
            msg.sender
        );
    }

    function _refresh(
        StreamMintPhaseState.PhaseState storage phaseState,
        IStreamMintManager.MintGateConfig storage gate,
        bytes32[] storage counterIds,
        mapping(bytes32 => IStreamMintManager.MintCounterConfig) storage counters,
        address[] storage executors,
        mapping(bytes32 => bytes32) storage policyHashes,
        Context memory x,
        uint64 graceUntil
    ) private returns (bytes32 policyHash) {
        uint256 collectionId = x.policy.collectionId;
        bytes32 phaseId = x.policy.phaseId;
        (bytes32[] memory ids, IStreamMintLedger.LedgerCounterPolicy[] memory ledgerPolicies) =
            StreamMintManagerAccounting.ledgerPolicies(counterIds, counters);
        policyHash = _computePolicyHash(phaseState, gate, counterIds, counters, executors, x);
        _recordArtistConsent(collectionId, phaseId, policyHash, x);
        policyHashes[phaseId] = policyHash;
        IStreamMintLedger(x.policy.ledger)
            .registerPhasePolicy(
                address(this), collectionId, phaseId, policyHash, ids, ledgerPolicies, graceUntil
            );
    }

    function _recordArtistConsent(
        uint256 collectionId,
        bytes32 phaseId,
        bytes32 policyHash,
        Context memory x
    ) private {
        (uint8 mode, bytes32 evidence) = StreamMintArtistConsent.registration(
            x.core,
            collectionId,
            phaseId,
            policyHash,
            IStreamGasParameterHost(address(this)).gasParameter(GGP_ARTIST_AUTHORITY_GAS_LIMIT)
        );
        emit MintPhaseConsentRecorded(
            SCHEMA_VERSION, collectionId, phaseId, policyHash, mode, evidence
        );
    }

    function _computePolicyHash(
        StreamMintPhaseState.PhaseState storage phaseState,
        IStreamMintManager.MintGateConfig storage gate,
        bytes32[] storage counterIds,
        mapping(bytes32 => IStreamMintManager.MintCounterConfig) storage counters,
        address[] storage executors,
        Context memory x
    ) private view returns (bytes32) {
        return StreamMintPhaseState.computeStoredPolicyHash(
            phaseState, gate, counterIds, counters, executors, x.policy
        );
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;
import "./StreamMintOperationIdentity.sol";
import "./StreamMintPhaseState.sol";
import "./StreamMintManagerAccounting.sol";
import "../../interfaces/stream/mint/StreamPreparedNativeContentTypes.sol";
import "../../interfaces/stream/revenue/StreamPreparedNativeSettlementTypes.sol";
import "../../interfaces/stream/revenue/StreamPreparedNativeRightsTypes.sol";

/// @notice Fixed decoding for retained Manager preview ABIs, outside Manager runtime headroom.
library StreamMintManagerViews {
    struct SubjectPreview {
        IStreamMintManager.CounterKeyMode keyMode;
        uint256 collectionId;
        bytes32 phaseId;
        bytes32 counterId;
        address payer;
        address recipient;
        address executor;
        address authorizer;
        bytes32 contextHash;
    }

    /// @notice Decodes the original static subject-preview request at the actual Manager.
    /// @dev Enum/address decoding remains strict; the fixed linked accounting call retains
    ///      Manager identity for its counter-config read and the original immutable Ledger.
    function subject(bytes calldata arguments, address ledger) external view returns (bytes32) {
        SubjectPreview memory p = abi.decode(arguments, (SubjectPreview));
        return StreamMintManagerAccounting.previewSubject(
            p.keyMode,
            StreamMintOperationIdentity.SubjectContext(
                block.chainid,
                ledger,
                p.collectionId,
                p.phaseId,
                p.counterId,
                p.payer,
                p.recipient,
                p.executor,
                p.authorizer,
                p.contextHash
            )
        );
    }

    function preparedEncoded(StreamPreparedNativeSettlementTypes.Facts storage facts)
        external view returns (bytes memory) { return abi.encode(facts); }

    function contentEncoded(StreamPreparedNativeContentTypes.Facts storage facts)
        external view returns (bytes memory) { return abi.encode(facts); }

    function rightsEncoded(StreamPreparedNativeRightsTypes.Facts storage facts)
        external view returns (bytes memory) { return abi.encode(facts); }

    function phaseEncoded(StreamMintPhaseState.PhaseState storage state)
        external view returns (bytes memory) { return abi.encode(state.exists, state.config); }

    function counterEncoded(IStreamMintManager.MintCounterConfig storage config)
        external view returns (bytes memory) { return abi.encode(config); }

    function gateEncoded(IStreamMintManager.MintGateConfig storage config)
        external view returns (bytes memory) { return abi.encode(config); }

    struct PhasePreview {
        uint256 collectionId;
        bytes32 phaseId;
        IStreamMintManager.MintPhaseConfig config;
        IStreamMintManager.MintGateConfig gate;
        bytes32[] counterIds;
        IStreamMintManager.MintCounterConfig[] counters;
        address[] executors;
    }

    function phasePolicy(bytes calldata arguments, address ledger, address registry)
        external
        view
        returns (bytes32)
    {
        PhasePreview memory p =
            abi.decode(bytes.concat(bytes32(uint256(32)), arguments), (PhasePreview));
        if (
            p.counterIds.length != p.counters.length || p.counterIds.length > 16
                || p.executors.length > 64
        ) {
            revert IStreamMintManager.MintArrayLengthMismatch();
        }
        return StreamMintOperationIdentity.computePolicyHash(
            p.config,
            p.gate,
            p.counterIds,
            p.counters,
            p.executors,
            StreamMintOperationIdentity.PolicyContext(
                block.chainid, address(this), ledger, registry, 1, p.collectionId, p.phaseId
            )
        );
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "./StreamMintOperationIdentity.sol";
import "./StreamMintCounterPreparation.sol";

/// @notice Typed stored-counter preparation shared by the immutable Manager's linked calls.
/// @dev Reads only the exact storage references supplied by Manager; adds no authority or state.
library StreamMintManagerAccounting {
    function previewSubject(
        IStreamMintManager.CounterKeyMode keyMode,
        StreamMintOperationIdentity.SubjectContext memory context
    ) external view returns (bytes32) {
        bytes32 definitionHash =
            IStreamMintManager(address(this))
        .counterConfig(context.collectionId, context.phaseId, context.counterId)
        .counterConfigHash;
        (, IStreamMintCounterPolicy.Definition memory d) =
            StreamMintCounterPolicy.read(context.ledger, definitionHash);
        (context.collectionId, context.phaseId) =
            StreamMintCounterPolicy.scopeIds(d.scope, context.collectionId, context.phaseId);
        return StreamMintOperationIdentity.subjectKey(keyMode, context);
    }

    function previewValue(
        address ledger,
        uint256 collectionId,
        bytes32 phaseId,
        bytes32 counterId,
        bytes32 subject
    ) external view returns (bytes32) {
        bytes32 definitionHash =
            IStreamMintManager(address(this))
        .counterConfig(collectionId, phaseId, counterId)
        .counterConfigHash;
        (, IStreamMintCounterPolicy.Definition memory d) =
            StreamMintCounterPolicy.read(ledger, definitionHash);
        (collectionId, phaseId) = StreamMintCounterPolicy.scopeIds(d.scope, collectionId, phaseId);
        return IStreamMintLedger(ledger)
            .deriveCounterValueKey(address(this), collectionId, phaseId, counterId, subject);
    }

    function counterConsumptions(
        IStreamMintManager.MintBatch calldata request,
        uint256 quantity,
        address authorizer,
        address ledger,
        bytes32[] storage storedCounterIds,
        mapping(
            bytes32 => IStreamMintManager.MintCounterConfig
        ) storage storedConfigs
    ) public view returns (IStreamMintLedger.CounterConsumption[] memory) {
        bytes32[] memory counterIds = new bytes32[](storedCounterIds.length);
        IStreamMintManager.MintCounterConfig[] memory counterConfigs =
            new IStreamMintManager.MintCounterConfig[](storedCounterIds.length);
        for (uint256 i = 0; i < storedCounterIds.length; i++) {
            bytes32 counterId = storedCounterIds[i];
            counterIds[i] = counterId;
            counterConfigs[i] = storedConfigs[counterId];
        }
        StreamMintOperationIdentity.CounterContext memory context =
            StreamMintOperationIdentity.CounterContext({
                chainId: block.chainid,
                manager: address(this),
                ledger: ledger,
                executor: msg.sender,
                authorizer: authorizer
            });
        return StreamMintCounterPreparation.prepare(
            request, quantity, counterIds, counterConfigs, context
        );
    }

    function ledgerPolicies(
        bytes32[] storage counterIds,
        mapping(bytes32 => IStreamMintManager.MintCounterConfig) storage storedConfigs
    )
        public
        view
        returns (bytes32[] memory ids, IStreamMintLedger.LedgerCounterPolicy[] memory policies)
    {
        ids = new bytes32[](counterIds.length);
        policies = new IStreamMintLedger.LedgerCounterPolicy[](counterIds.length);
        for (uint256 i = 0; i < counterIds.length; i++) {
            bytes32 counterId = counterIds[i];
            ids[i] = counterId;
            IStreamMintManager.MintCounterConfig memory config = storedConfigs[counterId];
            policies[i] = IStreamMintLedger.LedgerCounterPolicy({
                enabled: config.enabled,
                capMode: config.capMode,
                deltaMode: config.deltaMode,
                staticCap: config.staticCap,
                staticIncrement: config.staticIncrement,
                counterConfigHash: config.counterConfigHash
            });
        }
    }
}

